/*
    Dashboard Thống kê tốt nghiệp — DASH_StudentGraduation_GetData
    Nguồn: SIM_GraduationResult, SIM_ExamDate, SIM_Student, SIM_Class, SIM_Science, SIM_Course

    Lọc ngày theo CreatedDate (giống DASH_MainSummary_GetData / page tổng)
    @YearID — bắt buộc (SIM_GraduationResult.YearID hoặc SIM_ExamDate.YearID)
    @Semester — giữ tham số (UI); dữ liệu TN không có Semester nên không lọc theo HK
    @FromDate, @ToDate — tuỳ chọn; mặc định tháng hiện tại
    @ScienceID, @CourseID, @ClassID — tuỳ chọn
    @ResultSet: 1..6 trả 1 result set; NULL trả đủ

    Result set 1 — KPI summary
    Result set 2 — Đủ / chưa đủ điều kiện TN
    Result set 3 — Theo lớp
    Result set 4 — Theo khóa
    Result set 5 — Theo khoa
    Result set 6 — Phân bố xếp loại TN
*/

IF OBJECT_ID(N'dbo.DASH_StudentGraduation_GetData', N'P') IS NOT NULL
    DROP PROCEDURE dbo.DASH_StudentGraduation_GetData;
GO

CREATE PROCEDURE dbo.DASH_StudentGraduation_GetData
(
    @ScienceID nvarchar(1000) = NULL,
    @CourseID nvarchar(1000) = NULL,
    @ClassID nvarchar(1000) = NULL,
    @YearID int,
    @Semester tinyint = NULL,
    @FromDate datetime = NULL,
    @ToDate datetime = NULL,
    @ResultSet tinyint = NULL
)
AS
BEGIN
    SET NOCOUNT ON;

    IF @FromDate IS NULL
        SET @FromDate = DATEADD(MONTH, DATEDIFF(MONTH, 0, GETDATE()), 0);

    IF @ToDate IS NULL
        SET @ToDate = DATEADD(DAY, -1, DATEADD(MONTH, 1, DATEADD(MONTH, DATEDIFF(MONTH, 0, GETDATE()), 0)));

    -- Đảm bảo @ToDate bao gồm cả ngày cuối (đến 23:59:59)
    SET @ToDate = DATEADD(DAY, 1, @ToDate);
    SET @ToDate = DATEADD(SECOND, -1, @ToDate);

    Select
        SIM_GraduationResult.StudentID,
        SIM_Student.StudentCode,
        SIM_Student.ClassID,
        SIM_Class.ClassName,
        SIM_Class.ClassShortName,
        SIM_Class.ScienceID,
        SIM_Science.ScienceName,
        SIM_Class.CourseID,
        SIM_Course.CourseName,
        SIM_GraduationResult.ResultReview,
        SIM_GraduationResult.CerIssued,
        SIM_GraduationResult.CerNo,
        SIM_GraduationResult.DecisionNo,
        SIM_GraduationResult.GraduationLevel,
        SIM_GraduationResult.Signingdate,
        SIM_GraduationResult.CreatedDate,
        IsNull(SIM_GraduationResult.YearID, SIM_ExamDate.YearID) as YearID,
        Case
            When SIM_GraduationResult.CerIssued = 1 Then 1
            When IsNull(LTrim(RTrim(SIM_GraduationResult.GraduationLevel)), N'') <> N'' Then 1
            When IsNull(LTrim(RTrim(SIM_GraduationResult.DecisionNo)), N'') <> N'' Then 1
            Else 0
        End as IsEligible
    Into #tblGraduationView
    From SIM_GraduationResult
        Inner Join SIM_ExamDate On SIM_ExamDate.ExamDateID = SIM_GraduationResult.ExamDateID
        Inner Join SIM_Student On SIM_Student.StudentID = SIM_GraduationResult.StudentID
        Inner Join SIM_Class On SIM_Class.ClassID = SIM_Student.ClassID
        Inner Join SIM_Science On SIM_Science.ScienceID = SIM_Class.ScienceID
        Inner Join SIM_Course On SIM_Course.CourseID = SIM_Class.CourseID
    Where SIM_GraduationResult.ResultReview = 1
        And SIM_Student.IsDeleted = 0
        And SIM_Class.IsActived = 1
        And SIM_Class.ClassType = 0
        And SIM_GraduationResult.CreatedDate >= @FromDate
        And SIM_GraduationResult.CreatedDate <= @ToDate
        And (
            IsNull(SIM_GraduationResult.YearID, SIM_ExamDate.YearID) = @YearID
        )
        And (@ClassID is null or @ClassID = N'' or CHARINDEX(',' + SIM_Student.ClassID + ',', ',' + @ClassID + ',') > 0)
        And (@ScienceID is null or @ScienceID = N'' or CHARINDEX(',' + SIM_Class.ScienceID + ',', ',' + @ScienceID + ',') > 0)
        And (@CourseID is null or @CourseID = N'' or CHARINDEX(',' + SIM_Class.CourseID + ',', ',' + @CourseID + ',') > 0);

    /* Result set 1 — KPI */
    IF @ResultSet IS NULL OR @ResultSet = 1
    BEGIN
        Declare @TotalReviewStudent int;
        Declare @EligibleStudent int;
        Declare @NotEligibleStudent int;
        Declare @TotalClass int;
        Declare @GraduationRate decimal(18, 1);

        Select
            @TotalReviewStudent = Count(*),
            @EligibleStudent = Sum(Case When IsEligible = 1 Then 1 Else 0 End),
            @NotEligibleStudent = Sum(Case When IsEligible = 0 Then 1 Else 0 End),
            @TotalClass = Count(Distinct ClassID)
        From #tblGraduationView;

        Set @TotalReviewStudent = IsNull(@TotalReviewStudent, 0);
        Set @EligibleStudent = IsNull(@EligibleStudent, 0);
        Set @NotEligibleStudent = IsNull(@NotEligibleStudent, 0);
        Set @TotalClass = IsNull(@TotalClass, 0);

        If @TotalReviewStudent > 0
            Set @GraduationRate = Round((@EligibleStudent * 100.0) / @TotalReviewStudent, 1);
        Else
            Set @GraduationRate = 0;

        Select
            @TotalReviewStudent as TotalReviewStudent,
            @EligibleStudent as EligibleStudent,
            @NotEligibleStudent as NotEligibleStudent,
            @GraduationRate as GraduationRate,
            @TotalClass as TotalClass;
    END

    /* Result set 2 — Đủ / chưa đủ điều kiện TN */
    IF @ResultSet IS NULL OR @ResultSet = 2
    BEGIN
        Select
            N'Đủ điều kiện TN' as StatusName,
            Sum(Case When IsEligible = 1 Then 1 Else 0 End) as StudentCount
        From #tblGraduationView
        Union All
        Select
            N'Chưa đủ điều kiện TN' as StatusName,
            Sum(Case When IsEligible = 0 Then 1 Else 0 End) as StudentCount
        From #tblGraduationView;
    END

    /* Result set 3 — Theo lớp */
    IF @ResultSet IS NULL OR @ResultSet = 3
    BEGIN
        Select
            ClassID,
            ClassName,
            Count(*) as TotalCount,
            Sum(Case When IsEligible = 1 Then 1 Else 0 End) as EligibleCount,
            Sum(Case When IsEligible = 0 Then 1 Else 0 End) as NotEligibleCount,
            Case
                When Count(*) > 0 Then Round((Sum(Case When IsEligible = 1 Then 1 Else 0 End) * 100.0) / Count(*), 1)
                Else 0
            End as GraduationRate
        From #tblGraduationView
        Group by ClassID, ClassName
        Order by TotalCount desc, ClassName;
    END

    /* Result set 4 — Theo khóa */
    IF @ResultSet IS NULL OR @ResultSet = 4
    BEGIN
        Select
            CourseID,
            CourseName,
            Count(*) as TotalCount,
            Sum(Case When IsEligible = 1 Then 1 Else 0 End) as EligibleCount,
            Sum(Case When IsEligible = 0 Then 1 Else 0 End) as NotEligibleCount,
            Case
                When Count(*) > 0 Then Round((Sum(Case When IsEligible = 1 Then 1 Else 0 End) * 100.0) / Count(*), 1)
                Else 0
            End as GraduationRate
        From #tblGraduationView
        Group by CourseID, CourseName
        Order by CourseName;
    END

    /* Result set 5 — Theo khoa */
    IF @ResultSet IS NULL OR @ResultSet = 5
    BEGIN
        Select
            ScienceID,
            ScienceName,
            Count(*) as TotalCount,
            Sum(Case When IsEligible = 1 Then 1 Else 0 End) as EligibleCount,
            Sum(Case When IsEligible = 0 Then 1 Else 0 End) as NotEligibleCount,
            Case
                When Count(*) > 0 Then Round((Sum(Case When IsEligible = 1 Then 1 Else 0 End) * 100.0) / Count(*), 1)
                Else 0
            End as GraduationRate
        From #tblGraduationView
        Group by ScienceID, ScienceName
        Order by TotalCount desc, ScienceName;
    END

    /* Result set 6 — Phân bố xếp loại TN (chỉ SV đủ ĐK) */
    IF @ResultSet IS NULL OR @ResultSet = 6
    BEGIN
        Select
            Case
                When IsNull(LTrim(RTrim(GraduationLevel)), N'') = N'' Then N'Chưa xếp loại'
                Else LTrim(RTrim(GraduationLevel))
            End as GraduationLevel,
            Count(*) as StudentCount
        From #tblGraduationView
        Where IsEligible = 1
        Group by
            Case
                When IsNull(LTrim(RTrim(GraduationLevel)), N'') = N'' Then N'Chưa xếp loại'
                Else LTrim(RTrim(GraduationLevel))
            End
        Order by StudentCount desc, GraduationLevel;
    END

    Drop Table #tblGraduationView;
END
GO

/*
Exec dbo.DASH_StudentGraduation_GetData
    @YearID = 2025,
    @Semester = 1,
    @FromDate = '2026-07-01',
    @ToDate = '2026-07-31',
